5	/**
6	 * Converts evaluation results from a ResultsFile into a table format for display.
7	 * Processes test results, formats variables (including pretty-printing objects/arrays as JSON),
8	 * handles redteam prompts, and structures data for console table and HTML output.
9	 *
10	 * @param eval_ - The results file containing evaluation data (requires version >= 4)
11	 * @returns An EvaluateTable with formatted headers and body rows for display
12	 */
13	export function convertResultsToTable(eval_: ResultsFile): EvaluateTable {
14	  invariant(
15	    eval_.prompts,
16	    `Prompts are required in this version of the results file, this needs to be results file version >= 4, version: ${eval_.version}`,
17	  );
18	  // first we need to get our prompts, we can get that from any of the results in each column
19	  const results = eval_.results;
20	  const varsForHeader = new Set<string>();
21	  const varValuesForRow = new Map<number, Record<string, string>>();
22	
23	  const rowMap: Record<number, EvaluateTableRow> = {};
24	  for (const result of results.results) {
25	    // vars
26	    for (const varName of Object.keys(result.vars || {})) {
27	      varsForHeader.add(varName);
28	    }
29	
30	    const row = rowMap[result.testIdx] || {
31	      description: result.description || undefined,
32	      outputs: [],
33	      vars: result.vars
34	        ? Object.values(varsForHeader)
35	            .map((varName) => {
36	              const varValue = result.vars?.[varName] ?? '';
37	              if (typeof varValue === 'string') {
38	                return varValue;
39	              }
40	              return JSON.stringify(varValue, null, 2);
41	            })
42	            .flat()
43	        : [],
44	      test: result.testCase,
45	    };
46	
47	    // Get the actual prompt from response.prompt (provider-reported) or legacy redteamFinalPrompt
48	    // Check both result.response.metadata and result.metadata for legacy compatibility
49	    const actualPrompt =
50	      getActualPrompt(result.response) || (result.metadata?.redteamFinalPrompt as string);
51	
52	    if (result.vars && actualPrompt) {
53	      const varKeys = Object.keys(result.vars);
54	      if (varKeys.length === 1 && varKeys[0] !== 'harmCategory') {
55	        result.vars[varKeys[0]] = actualPrompt;
56	      } else if (varKeys.length > 1) {
57	        // NOTE: This is a hack. We should use config.redteam.injectVar to determine which key to update but we don't have access to the config here
58	        const targetKeys = ['prompt', 'query', 'question'];
59	        const keyToUpdate = targetKeys.find((key) => result.vars[key]);
60	        if (keyToUpdate) {
61	          result.vars[keyToUpdate] = actualPrompt;
62	        }
63	      }
64	    }
65	
66	    // Copy sessionId from metadata to vars for display if not already present
67	    // Multi-turn strategies (IterativeMeta, Crescendo, etc.) store multiple sessionIds in metadata.sessionIds array
68	    // Single-turn strategies store a single sessionId in metadata.sessionId
69	    if (!result.vars?.sessionId) {
70	      const metadataSessionIds = result.metadata?.sessionIds;
71	      if (Array.isArray(metadataSessionIds) && metadataSessionIds.length > 0) {
72	        result.vars = result.vars || {};
73	        result.vars.sessionId = metadataSessionIds
74	          .filter((id) => id != null && id !== '')
75	          .map(String)
76	          .join('\n');
77	        varsForHeader.add('sessionId');
78	      } else if (result.metadata?.sessionId) {
79	        result.vars = result.vars || {};
80	        result.vars.sessionId = result.metadata.sessionId;
81	        varsForHeader.add('sessionId');
82	      }
83	    }
84	
85	    // Copy transformDisplayVars from response metadata to vars for display
86	    // This handles layer mode where embeddedInjection is set at runtime, not in test case vars
87	    const transformDisplayVars = result.response?.metadata?.transformDisplayVars as
88	      | Record<string, string>
89	      | undefined;
90	    if (transformDisplayVars) {
91	      result.vars = result.vars || {};
92	      for (const [key, value] of Object.entries(transformDisplayVars)) {
93	        if (!result.vars[key]) {
94	          result.vars[key] = value;
95	          varsForHeader.add(key);
96	        }
97	      }
98	    }
99	
100	    varValuesForRow.set(result.testIdx, result.vars as Record<string, string>);
101	    rowMap[result.testIdx] = row;
102	
103	    // format text
104	    let resultText: string | undefined;
105	
106	    const rawOutput = result.response?.output;
107	    let outputTextDisplay: string;
108	    if (rawOutput !== null && typeof rawOutput === 'object') {
109	      outputTextDisplay = JSON.stringify(rawOutput);
110	    } else if (rawOutput == null || rawOutput === '') {
111	      outputTextDisplay = result.error || '';
112	    } else {
113	      outputTextDisplay = String(rawOutput);
114	    }
115	    if (result.testCase.assert) {
116	      if (result.success) {
117	        resultText = `${outputTextDisplay || result.error || ''}`;
118	      } else {
119	        resultText = `${outputTextDisplay}`;
120	      }
121	    } else if (result.error) {
122	      resultText = `${result.error}`;
123	    } else {
124	      resultText = outputTextDisplay;
125	    }
126	
127	    row.outputs[result.promptIdx] = {
128	      id: result.id || `${result.testIdx}-${result.promptIdx}`,
129	      ...result,
130	      text: resultText || '',
131	      prompt: result.prompt.raw,
132	      provider: result.provider?.label || result.provider?.id || 'unknown provider',
133	      pass: result.success,
134	      failureReason: result.failureReason,
135	      cost: result.cost || 0,
136	      tokenUsage: result.tokenUsage,
137	      audio: result.response?.audio
138	        ? {
139	            id: result.response.audio.id,
140	            expiresAt: result.response.audio.expiresAt,
141	            data: result.response.audio.data,
142	            blobRef: result.response.audio.blobRef,
143	            transcript: result.response.audio.transcript,
144	            format: result.response.audio.format,
145	            sampleRate: result.response.audio.sampleRate,
146	            channels: result.response.audio.channels,
147	            duration: result.response.audio.duration,
148	          }
149	        : undefined,
150	      video: result.response?.video
151	        ? {
152	            id: result.response.video.id,
153	            blobRef: result.response.video.blobRef,
154	            storageRef: result.response.video.storageRef,
155	            url: result.response.video.url,
156	            format: result.response.video.format,
157	            size: result.response.video.size,
158	            duration: result.response.video.duration,
159	            thumbnail: result.response.video.thumbnail,
160	            spritesheet: result.response.video.spritesheet,
161	            model: result.response.video.model,
162	            aspectRatio: result.response.video.aspectRatio,
163	            resolution: result.response.video.resolution,
164	          }
165	        : undefined,
166	      images: result.response?.images?.map((img) => ({
167	        data: img.data,
168	        blobRef: img.blobRef,
169	        mimeType: img.mimeType,
170	      })),
171	    };
172	    invariant(result.promptId, 'Prompt ID is required');
173	
174	    row.testIdx = result.testIdx;
175	  }
176	
177	  const rows = Object.values(rowMap);
178	  const sortedVars = [...varsForHeader].sort();
179	  for (const row of rows) {
180	    row.vars = sortedVars.map((varName) => {
181	      const varValue = varValuesForRow.get(row.testIdx)?.[varName] ?? '';
182	      if (typeof varValue === 'string') {
183	        return varValue;
184	      }
